begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','style_learning_proposals','Las propuestas tienen versiones y evidencia');
select has_table('public','style_learning_settings','La autorización automática es explícita');
select ok((select relrowsecurity from pg_class where oid='public.style_learning_proposals'::regclass),'Propuestas protegidas por RLS');
select ok((select relrowsecurity from pg_class where oid='public.style_learning_settings'::regclass),'Autorización protegida por RLS');
select ok(not has_table_privilege('authenticated','public.style_learning_proposals','SELECT'),'Las versiones internas se leen por acceso de usuario validado');
select ok(not has_table_privilege('anon','public.style_learning_settings','SELECT'),'No se exponen autorizaciones');
select ok(not has_function_privilege('authenticated','public.decide_style_learning(uuid,uuid,uuid,uuid,text,boolean)','EXECUTE'),'El navegador no aplica ni revierte cambios directamente');
select ok(not has_function_privilege('anon','public.set_style_learning_settings(uuid,uuid,boolean,uuid,text)','EXECUTE'),'La autorización no es anónima');
select ok(not has_function_privilege('authenticated','public.refresh_style_learning(integer)','EXECUTE'),'La agregación es exclusiva del worker');
select ok(has_function_privilege('service_role','public.refresh_style_learning(integer)','EXECUTE'),'El worker puede agregar patrones');
select is(public.style_learning_phrases('greeting','NONE','es'),'[]'::jsonb,'La retirada usa una operación cerrada, sin texto recibido');
select is(public.style_learning_phrases('closing','SHORT','es'),'["Un saludo"]'::jsonb,'Las propuestas solo incorporan fórmulas predefinidas');
select ok(not public.style_learning_evidence_valid('{"support":1,"total":1,"threads":1,"days":1,"audiences":1}'::jsonb,true),'Una corrección no modifica el perfil');
select ok(not public.style_learning_evidence_valid('{"support":5,"total":5,"threads":4,"days":2,"audiences":1}'::jsonb,true),'El perfil general requiere diversidad de destinatarios');
select ok(not public.style_learning_evidence_valid('{"support":5,"total":7,"threads":4,"days":2,"audiences":3}'::jsonb,true),'Se requiere al menos un ochenta por ciento de apoyo');
select ok(public.style_learning_evidence_valid('{"support":5,"total":6,"threads":4,"days":2,"audiences":3}'::jsonb,true),'Un patrón general consistente reúne la evidencia necesaria');
select has_index('public','style_learning_proposals','style_learning_proposals_profile_owner_idx','La referencia de perfil tiene índice de propietario');
select has_index('public','generation_runs','generation_runs_style_learning_idx','La consulta de evidencia por versión tiene índice');
select * from finish();
rollback;
